// Local dev server: `npm start` -> http://localhost:3000
// (The live GitHub Pages site is generated by build.js instead.)
const path = require('path');
const express = require('express');
const { getPages, notFoundPage, commonLocals } = require('./lib/site');
const { getBlogPage } = require('./lib/blog');
const { createRouter: createAdminRouter } = require('./lib/admin');

const app = express();
const PORT = process.env.PORT || 3000;

app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));
app.use(express.static(path.join(__dirname, 'public')));

app.use((req, res, next) => {
  Object.assign(res.locals, commonLocals, {
    base: '',
    year: new Date().getFullYear(),
    currentPath: req.path.endsWith('/') ? req.path : req.path + '/',
  });
  next();
});

app.use('/admin', createAdminRouter());

getPages().forEach((page) => {
  app.get(page.url, (req, res) => res.render(page.view, page.locals));
});

app.get(['/blogs/', '/blogs/:slug/'], async (req, res) => {
  const page = await getBlogPage(req.params.slug);
  res.status(page.status).render(page.view, page.locals);
});

app.use((req, res) => {
  res.status(404).render(notFoundPage.view, notFoundPage.locals);
});

app.listen(PORT, () => {
  console.log(`Calculator Worlds running at http://localhost:${PORT}`);
});
